const edition3Groups=[{"key": "news", "label": "📰 AI 뉴스", "items": [{"t": "덴마크, AI 딥페이크 무단 공유 금지 법안 발의", "u": "https://www.reuters.com/world/denmark-plans-ban-sharing-ai-deepfakes-without-consent-2026-10-08/", "d": "2026-10-08", "s": "Reuters", "q": ["덴마크가 AI로 만든 가짜 얼굴·목소리(딥페이크)를 허락 없이 공유하는 걸 금지하는 법을 발의했어요.", "패러디나 풍자는 예외지만, 사람을 속이는 가짜 영상은 불법이 돼요.", "빅테크에는 조작 콘텐츠를 빨리 지우라는 의무도 붙었어요."], "w": "'얼굴 도둑질'에 처음으로 국가가 잠금장치를 거는 거예요. AI 가짜 영상 시대의 첫 '저작권법' 같은 순간이에요.", "a": ["딥페이크 규제 전쟁 — 각국 법안 비교", "딥페이크 탐지 기술, 어디까지 왔나"]}, {"t": "텐센트, AI 투자 자금 마련 위해 최대 50억 달러 채권 발행 검토", "u": "https://www.reuters.com/world/asia-pacific/tencent-mulls-5-billion-bond-sale-push-ai-ambitions-bloomberg-news-reports-2026-10-08/", "d": "2026-10-08", "s": "Reuters", "q": ["중국 텐센트가 AI 투자 자금을 마련하려고 최대 50억 달러(약 7조 원)짜리 채권을 팔 방안을 검토 중이에요.", "6월에도 46억 달러를 빌렸으니, 1년에 두 번 대형 자금 조달인 셈이에요.", "돈은 주로 AI·컴퓨팅 인프라에 들어갈 예정이에요."], "w": "'AI하려면 돈이 먼저'라는 게 빅테크들의 공통 과제예요. 채권 발행은 AI 전쟁의 군자금 마련 작전이에요.", "a": ["빅테크 AI 군자금 지도 — 누가 얼마를 태우고 있나", "중국 AI 투자, 텐센트의 승부수"]}, {"t": "WSJ 보고서: \"AI 투자가 기업 성과로 이어지지 않는다\" — 오케스트레이션 격차", "u": "https://www.advanced-television.com/2026/10/08/report-ai-investment-not-driving-enterprise-performance/", "d": "2026-10-08", "s": "WSJ Intelligence", "q": ["WSJ 인텔리전스가 전 세계 C레벨 임원 801명을 조사했더니, 기업들이 평균 183개의 AI 도구를 쓴대요.", "그런데 85%는 서로 연결돼 있지 않아 투자 대비 성과가 안 나온대요.", "보고서는 이걸 '오케스트레이션 격차'라고 불렀어요."], "w": "'악기는 183개인데 지휘자가 없는 오케스트라'예요. 도구를 많이 사는 게 아니라 잘 엮는 게 관건이에요.", "a": ["기업 AI 도입의 진짜 병목 — 연결이냐, 도구냐", "오케스트레이션 격차 줄이는 실전 체크리스트"]}, {"t": "Meta의 AI 에이전트 'Muse', 모바일 출시 한 달 만에 아이패드 앱 출시", "u": "https://techcrunch.com/2026/10/07/metas-muse-launches-on-ipad-just-a-month-after-its-mobile-debut/", "d": "2026-10-07", "s": "TechCrunch", "q": ["Meta의 개인 AI 비서 'Muse'가 아이패드 전용 앱을 내놨어요. 모바일 출시 한 달 만이에요.", "누적 설치가 660만 건을 넘었고, Asana·Figma·QuickBooks 같은 중소기업용 업무 연결도 추가됐어요.", "Meta의 차세대 가젯에도 Muse가 탑재될 예정이라고 전해졌어요."], "w": "'손 안의 비서'가 '책상 위의 비서'가 된 거예요. Meta가 AI 비서를 기기마다 심는 속도가 무섭게 빨라요.", "a": ["Muse vs ChatGPT vs Claude — 개인 비서 3파전", "아이패드 AI 비서 실전 리뷰"], "img": "images/img32.jpg", "alt": "Meta AI 에이전트 Muse 아이패드 앱 출시 기사"}, {"t": "OpenAI, 'ChatGPT for Teens'에 대학 입시 플래너 추가", "u": "https://foxbusiness.com/technology/openai-launches-college-planner-chatgpt-teens-track-application-financial-aid", "d": "2026-10-07", "s": "Fox Business", "q": ["OpenAI가 청소년용 ChatGPT에 대학 입시 플래너를 넣는다고 발표했어요.", "지원서 요건·마감일·학자금 지원 절차를 정리해주는 기능이에요.", "미국 10~12학년 학생들이 먼저 쓸 수 있어요."], "w": "'AI 선생님'이 'AI 입시 컨설턴트'가 된 거예요. 청소년 AI 시장을 선점하려는 OpenAI의 한 수예요.", "a": ["AI 입시 컨설턴트 시대 — 사교육의 미래", "ChatGPT for Teens 안전 장치는?"]}, {"t": "Anthropic Claude, 리만 가설 하한 41.6% → 67.2%로 끌어올려", "u": "https://tech-insider.org/anthropic-claude-riemann-hypothesis-breakthrough-2026/", "d": "2026-10-07", "s": "tech-insider", "q": ["미공개 Claude 연구 버전이 수학 최대 난제 '리만 가설'의 관련 하한 값을 41.6%에서 67.2%로 끌어올렸대요.", "Lean 형식 증명으로 검증됐고, 이 분야의 오랜 기록을 깼대요.", "OpenAI가 수학 미해결 문제 722편을 공개한 데 이은 '프론티어 AI 수학 대결' 구도예요."], "w": "'AI가 수학 난제를 푼다'는 말이 현실이 되고 있어요. 수학계의 게임 체인저는 이제 AI예요.", "a": ["AI 수학자 시대 — 리만 가설은 언제 풀릴까", "OpenAI vs Anthropic, 수학 증명 대결"]}, {"t": "[국내] 금감원 \"AI 해킹, IP 차단만으론 한계\"…금융권에 탐지 강화 주문", "u": "https://www.newsis.com/view/NISX20261008_0003818345", "d": "2026-10-08", "s": "뉴시스", "q": ["금융감독원이 AI 해킹 대응은 IP 차단만으로는 한계가 있다고 밝혔어요.", "공격자가 프록시로 IP를 계속 바꿔가며 공격하기 때문이래요.", "대신 요청·응답의 '행위' 자체를 분석하는 탐지를 금융권에 주문했어요."], "w": "'문을 잠가도 도둑이 변장하고 들어온다'는 거예요. 얼굴이 아니라 행동을 보는 보안으로 바뀌는 순간이에요.", "a": ["AI 해킹 시대의 금융 보안 — IP 차단의 종말", "행위 기반 탐지란?"]}, {"t": "[국내] 이억원 금융위원장 \"AI 해킹은 AI로 막아야\"…망분리 규제 완화 시사", "u": "https://www.newsis.com/view/NISX20261008_0003818973", "d": "2026-10-08", "s": "뉴시스", "q": ["이억원 금융위원장이 10월 8일 국정감사에서 \"AI 해킹은 AI로 막아야 한다\"고 말했어요.", "보안 목적의 AI 활용은 불가피하다며 망분리 규제 완화를 검토하겠다고 했어요.", "국내 금융권 AI 해킹이 연쇄적으로 터진 데 대한 후속 조치예요."], "w": "'칼에 맞서려면 칼이 필요하다'는 선언이에요. 한국 금융 보안의 근본 규칙이 바뀌기 시작했어요.", "a": ["망분리 규제 완화 — 뭐가 달라지나", "금융권 AI 해킹 연쇄 사건 정리"]}, {"t": "Healthleap, 병원 환자 기록 읽는 AI로 3,800만 달러 유치", "u": "https://techcrunch.com/2026/10/07/healthleap-raises-38m-for-its-ai-that-flags-hospital-patients-who-may-need-a-closer-look/", "d": "2026-10-07", "s": "TechCrunch", "q": ["환자 차트에서 영양실조·섬망 같은 놓치기 쉬운 질환 위험을 AI로 찾아내는 Healthleap이 3,800만 달러를 유치했어요.", "시드 800만 달러에 이어 시리즈A 3,000만 달러예요.", "50개 이상 병원에 도입됐고 매출이 10배 뛰었대요."], "w": "'차트를 읽는 두 번째 눈'이 병원 필수품이 되고 있어요. 의료 AI는 이제 연구가 아니라 장사예요.", "a": ["의료 AI 투자 지도 — 돈이 가는 곳", "병원에 들어온 AI, 실제 효과는?"], "img": "images/img33.jpg", "alt": "Healthleap 3800만 달러 유치 기사"}]}, {"key": "models", "label": "🚀 모델·제품 릴리스", "items": [{"t": "Amazon Nova 2.5 Sonic (Bedrock GA) — 실시간 음성 에이전트 모델", "u": "https://aws.amazon.com/about-aws/whats-new/2026/10/amazon-nova-2.5-sonic/", "d": "2026-10-05", "s": "AWS", "q": ["아마존의 실시간 음성 에이전트 모델 'Nova 2.5 Sonic'이 Bedrock에서 정식 출시됐어요.", "말을 듣고 바로 말로 대답하는 'speech-to-speech' 모델이에요.", "주문 조회 같은 일을 대화 중간에도 끊김 없이 처리하는 비동기 도구 호출이 강점이에요."], "w": "'전화받는 AI 직원'의 표준 부품이 나온 거예요. 콜센터가 AI로 바뀌는 속도가 더 빨라져요.", "a": ["음성 AI 에이전트 전쟁 — Nova vs GPT 음성 모드", "콜센터 AI 도입 실전 가이드"]}, {"t": "VIDRAFT Darwin-180B-RSI — 180B 오픈웨이트 모델", "u": "https://dev.to/ai_openfree_b23025ef075cf/open-180b-model-leads-10-official-hugging-face-leaderboards-and-the-zero-token-judge-behind-it-2gac", "d": "2026-10-06", "s": "dev.to", "q": ["Qwen3.8-Flash-Next 기반의 1800억짜리 오픈웨이트 모델이 나왔어요.", "허깅페이스 공식 리더보드 10개에서 1위를 차지했대요.", "토큰을 생성하지 않고 내부 상태를 읽어 0.06초 만에 판단하는 'Zero-Token Judge' 기법도 함께 공개됐어요."], "w": "'말 안 하고 속으로 판단하는' AI예요. 점수 매기는 AI의 속도가 비약적으로 빨라졌어요.", "a": ["Zero-Token Judge — 평가 AI의 새 방식", "오픈웨이트 180B, 내 GPU에서 돌릴 수 있을까"]}]}, {"key": "papers", "label": "📄 논문", "items": [{"t": "AI 에이전트가 기후 모델을 만들 수 있을까? (SciExam for ENSO)", "u": "https://arxiv.org/abs/2610.10513", "d": "2026-10-07", "s": "arXiv cs.AI", "q": ["AI 에이전트들에게 6시간을 주고 엘니뇨 기후 모델을 직접 만들게 했어요.", "12개 중 6개가 학계 발표 모델보다 성적이 좋았대요.", "정답이 없는 과학 연구도 AI가 할 수 있다는 걸 보여준 실험이에요."], "w": "'과학자 AI'가 교과서가 아니라 연구실에서 일하기 시작했어요. 기후 과학의 주역이 바뀌고 있어요.", "a": ["AI 과학자 — 실험실에 들어온 에이전트", "SciExam으로 기후 모델 만들기"]}, {"t": "로봇 세계 모델의 스케일링 법칙 (RoboJEPA)", "u": "https://arxiv.org/abs/2610.10515", "d": "2026-10-07", "s": "arXiv cs.AI", "q": ["로봇이 세상을 머릿속에 그리는 '세계 모델'도 크게 만들수록 예측이 좋아진다는 법칙을 처음 증명했어요.", "80억짜리 역대 최대 JEPA 모델도 함께 공개됐어요.", "로봇의 '상상력'에도 규모 법칙이 통한다는 거예요."], "w": "'로봇도 크면 똑똑해진다'는 공식이 나온 거예요. 휴머노이드 시대의 엔진 설계도가 그려졌어요.", "a": ["로봇 스케일링 법칙 — GPT 모먼트는 올까", "JEPA란? Yann LeCun의 세계 모델"]}, {"t": "찾는 게 아니라 '만들어내는' 검색 증강 생성 (RECAST)", "u": "https://arxiv.org/abs/2610.10507", "d": "2026-10-07", "s": "arXiv cs.CL", "q": ["기존 RAG는 문서를 '찾아오기'만 했다면, RECAST는 여러 자료를 필터링·계산·조합해서 근거를 직접 '조리'해요.", "답에 필요한 증거를 적응적으로 배분하는 방식이에요.", "정확도가 크게 올랐다고 해요."], "w": "'도서관 사서'에서 '요리사'로 진화한 AI예요. 재료를 찾아오는 게 아니라 요리를 해줘요.", "a": ["RAG 2.0 — 검색 증강 생성의 진화", "RECAST 원리 ELI5"]}, {"t": "LLM 지식을 메모장처럼 따로 고치기 (EngramEdit)", "u": "https://arxiv.org/abs/2610.10533", "d": "2026-10-07", "s": "arXiv cs.CL", "q": ["모델 본체는 건드리지 않고 '조건부 메모리'라는 별도 지식 서랍만 수술해서 틀린 사실을 고치는 기술이에요.", "다른 지식은 거의 손상 없이 업데이트 성공률이 거의 100%래요.", "AI의 '기억'을 부분 교체하는 방식이에요."], "w": "'뇌 수술 없이 메모장만 고치는' AI예요. AI 업데이트가 훨씬 싸고 안전해질 수 있어요.", "a": ["AI 지식 편집 — 모델 업데이트의 미래", "EngramEdit 실전 데모"]}, {"t": "강화학습에서 '탐험'과 '공부'를 분리하자 (Decoupling Exploration from Optimization in RLVR)", "u": "https://arxiv.org/abs/2610.10536", "d": "2026-10-07", "s": "arXiv cs.LG", "q": ["모험심 많은 탐험가 모델과 착실한 우등생 모델을 따로 뒀어요.", "탐험가는 막 실험하고, 우등생은 좋은 것만 골라 배우는 방식이에요.", "기존 학습법보다 수학 문제 풀이에서 더 셌대요."], "w": "'놀 때는 놀고 공부할 땐 공부하는' AI예요. 역할 분담이 학습 효율을 확 높였어요.", "a": ["RLVR의 새 학습법 — 탐험과 최적화 분리", "AI 수학 실력, 어떻게 키울까"]}, {"t": "잊으려면 오히려 더 많이 외워야 한다 (Forget-Only Unlearning)", "u": "https://arxiv.org/abs/2610.10519", "d": "2026-10-07", "s": "arXiv cs.LG", "q": ["AI에게 특정 데이터를 '잊게' 하려면, 역설적이게도 학습 때 버린 정보까지 어딘가에 보관하고 있어야 한대요.", "이걸 수학적으로 증명한 논문이에요.", "머신 언러닝의 역설 같은 발견이에요."], "w": "'잊으려면 기억해야 한다'는 AI의 딜레마예요. 개인정보 삭제 요청 시대의 핵심 난제예요.", "a": ["AI 망각의 역설 — 잊어버리기란 무엇인가", "머신 언러닝, 개인정보 삭제는 가능한가"]}, {"t": "로봇판 수능 시험장 (RobotWorld)", "u": "https://arxiv.org/abs/2610.10409", "d": "2026-10-07", "s": "arXiv cs.AI", "q": ["조작·이동·주행·비행까지 84개 과제로 AI 에이전트의 '몸 쓰는 능력'을 재는 시뮬레이션 시험장이에요.", "디지털에선 똑똑해도 현실 세계에선 자주 삐끗한다는 게 드러났대요.", "다양한 로봇 몸에 적용되는 멀티모달 벤치마크예요."], "w": "'말 잘하는 AI'와 '몸 잘 쓰는 AI'는 다르다는 걸 보여주는 시험장이에요. 로봇 수능이 시작됐어요.", "a": ["로봇 수능 — AI의 몸은 얼마나 똑똑한가", "RobotWorld 벤치마크 뜯어보기"]}, {"t": "AI 에이전트의 '거짓말' 측정기 (DecepEval)", "u": "https://arxiv.org/abs/2610.07967", "d": "2026-10-06", "s": "HF Papers 트렌딩", "q": ["압박·유인·갈등 상황에서 AI 에이전트가 슬쩍 거짓말을 하는지를 재는 1,532개 문항 벤치마크예요.", "최신 모델 9개를 재보니 유인만 주면 거짓말이 늘었대요.", "HF Papers 트렌딩에 오른 안전 연구예요."], "w": "'AI도 꾀를 부린다'는 걸 수치로 잡은 거예요. 에이전트 시대의 거짓말 탐지기가 필요해요.", "a": ["AI 거짓말 탐지기 — DecepEval 뜯어보기", "에이전트 안전, 어디까지 왔나"]}]}, {"key": "open", "label": "💻 오픈소스·스킬", "items": [{"t": "NVIDIA/OpenShell — 자율 AI 에이전트용 오픈소스 안전 실행 런타임", "u": "https://github.com/NVIDIA/OpenShell", "d": "2026-09-28", "s": "GitHub", "q": ["엔비디아의 AI 에이전트 안전 실행 런타임이에요.", "커널 레벨 격리로 파일·프로세스·네트워크·자격증명을 통제하고, 정책은 YAML로 선언해요.", "Claude Code·Codex·OpenCode 같은 코딩 에이전트를 지원하고 Apache 2.0 라이선스예요."], "w": "'AI에게 줄 수 있는 안전한 놀이터'예요. 에이전트가 날뛰어도 OS가 붙잡아줘요.", "a": ["OpenShell로 에이전트 샌드박스 만들기", "AI 에이전트 보안 — 커널 격리란"], "img": "images/img34.jpg", "alt": "NVIDIA OpenShell GitHub 저장소"}, {"t": "alibaba/open-code-review — LLM 에이전트 결합형 하이브리드 코드 리뷰 도구", "u": "https://github.com/alibaba/open-code-review", "d": "2026-10", "s": "GitHub", "q": ["알리바바 규모의 실전 검증된 코드 리뷰 도구예요.", "결정적 파이프라인과 LLM 에이전트를 섞은 하이브리드 구조예요.", "NPE·스레드 안전성·XSS·SQL 인젝션 같은 다언어 규칙이 내장돼 있어요."], "w": "'AI 리뷰어와 규칙 리뷰어의 콤비'예요. 코드 리뷰가 자동으로, 그것도 꼼꼼하게 돼요.", "a": ["AI 코드 리뷰 — 어디까지 믿을까", "open-code-review 실전 도입기"]}, {"t": "Tencent/WeKnora — 오픈소스 LLM 지식 플랫폼", "u": "https://github.com/Tencent/WeKnora", "d": "2026-10", "s": "GitHub", "q": ["원시 문서를 쿼리 가능한 RAG, 자율 추론 에이전트, 스스로 유지되는 위키로 바꿔주는 텐센트의 오픈소스 지식 플랫폼이에요.", "기업 문서 관리 자동화용 재료로 쓸 수 있어요.", "월간 트렌딩에 진입했어요."], "w": "'회사 문서 창고를 살아있는 비서로 바꾸는' 도구예요. 사내 지식 검색의 판도가 바뀌어요.", "a": ["WeKnora로 사내 지식 비서 만들기", "기업 RAG 오픈소스 비교"]}, {"t": "JustVugg/colibri — 순수 C로 만든 MoE 모델 초경량 실행 엔진", "u": "https://github.com/JustVugg/colibri", "d": "2026-10", "s": "GitHub", "q": ["순수 C, 의존성 제로로 만든 MoE 모델 초경량 실행 엔진이에요.", "전문가 가중치를 디스크에서 스트리밍해서 돌려요.", "온디바이스 대형 모델 실험용으로 주목받고 있어요."], "w": "'무거운 AI를 가벼운 몸에 싣는' 기술이에요. 내 컴퓨터에서도 거대 모델을 돌릴 길이 열려요.", "a": ["colibri로 거대 모델 로컬 실행", "초경량 추론 엔진 비교"]}, {"t": "tashfeenahmed/freellmapi — 무료 LLM 제공업체 34곳을 하나의 API로", "u": "https://github.com/tashfeenahmed/freellmapi", "d": "2026-10", "s": "GitHub", "q": ["무료 LLM 제공자 34곳·엔드포인트 635개를 OpenAI 호환 단일 API로 묶은 게이트웨이예요.", "월 74억 토큰 분량, 스마트 라우팅·자동 페일오버를 지원해요.", "이번 달 스타가 6,960개 늘어난 급상승 프로젝트예요."], "w": "'공짜 AI 뷔페의 통합 식권'이에요. 개인 실험용 AI 비용이 사실상 0원이 돼요.", "a": ["freellmapi로 무료 AI 실험실 차리기", "무료 LLM 제공자 지도"]}, {"t": "Together Link — 무료 CLI로 Claude Code에 오픈모델 연결", "u": "https://www.marktechpost.com/2026/10/05/meet-together-link-a-free-cli-that-runs-open-models-like-kimi-k3-and-glm-5-3-inside-claude-code-codex-and-opencode/", "d": "2026-10-05", "s": "MarkTechPost", "q": ["Together AI의 무료 CLI 도구예요.", "Claude Code·Codex·OpenCode에 Kimi K3·GLM-5.3 같은 오픈모델을 연결해줘요.", "MIT 라이선스로 누구나 쓸 수 있어요."], "w": "'유료 AI 비서의 자리에 공짜 AI를 앉히는' 도구예요. 코딩 에이전트의 선택지가 확 넓어져요.", "a": ["Together Link로 오픈모델 코딩 에이전트", "코딩 에이전트 비용 0원 도전"]}]}, {"key": "data", "label": "📊 데이터셋", "items": [{"t": "LightwheelAI/EgoStandard — 9만 시간 1인칭 시점 영상 + 3D 손 포즈", "u": "https://huggingface.co/datasets/LightwheelAI/EgoStandard", "d": "2026-10-01", "s": "Hugging Face", "q": ["머리 시점 1인칭 영상 9만 시간에 동기화된 3D 손 포즈를 붙인 대형 데이터셋이에요.", "로봇·웨어러블 학습용이고, 얼굴·번호판은 자동 비식별 처리됐어요.", "접근 승인이 필요해요."], "w": "'AI에게 9만 시간의 눈을 빌려주는' 자료예요. 로봇이 사람 손을 배우는 교과서예요.", "a": ["1인칭 데이터셋 — 로봇 학습의 연료", "EgoStandard 활용 사례"]}, {"t": "bakrianoo/jabarti-llm-dataset — 아랍어 QA LLM 데이터셋 751만 행", "u": "https://huggingface.co/datasets/bakrianoo/jabarti-llm-dataset", "d": "2026-09-23", "s": "Hugging Face", "q": ["아랍어 질의응답 751만 행 데이터셋이에요.", "난이도와 유형 라벨이 붙어 있어 파인튜닝·평가에 쓸 수 있어요.", "아랍어 LLM 생태계의 핵심 연료예요."], "w": "'영어 중심 AI'에서 벗어나는 한 걸음이에요. 언어별 AI 주권 경쟁이 치열해져요.", "a": ["아랍어 LLM — 언어 주권 시대", "다국어 데이터셋 지도"]}, {"t": "MoreThought/Fable-5.1-Max-Reasoning-Filtered — 추론 필터링 데이터셋", "u": "https://huggingface.co/datasets/MoreThought/Fable-5.1-Max-Reasoning-Filtered-10000x", "d": "2026-09-24", "s": "Hugging Face", "q": ["고품질로 필터링된 추론 중심 데이터셋이에요.", "15k 행에 4.88k 다운로드, 소형 모델 추론 능력 강화용 학습 재료로 트렌딩 중이에요.", "'잘 고른 문제집' 같은 자료예요."], "w": "'데이터 양보다 질'이 추론 AI의 핵심이라는 증거예요. 작은 모델도 좋은 문제집이면 똑똑해져요.", "a": ["추론 데이터셋 — 작은 모델 키우기", "Fable 데이터셋 실전 활용"]}]}];
const edition4Groups=[{"key":"news","label":"📰 AI 뉴스","items":[{"t":"구글, AI가 만든 사진·영상·음성 판별 사이트 'SynthID' 전 세계 공개","u":"https://techcrunch.com/2026/10/07/googles-new-synthid-website-can-identify-ai-generated-media/","d":"2026-10-07","s":"TechCrunch","q":["구글이 2023년부터 써온 'SynthID' 워터마크 판별기를 일반인에게 열었어요.","사진·영상·음성을 올리면 AI가 만들었는지 눈 깜짝할 새 알려줘요.","지금까지 1,800억 장의 이미지·영상이 이 보이지 않는 도장을 찍혔대요."],"w":"AI가 만든 가짜와 진짜를 가리는 '도장 감별기'가 모두의 주머니에 들어온 셈이에요. 가짜뉴스 구별이 전문가 일이 아니라 일상이 돼요.","a":["SynthID 실전 테스트 — 가짜 이미지 구별 챌린지","AI 워터마크 전쟁: 구글 vs OpenAI vs 애플"],"img":"images/img30.jpg","alt":"구글 SynthID 판별 사이트 공개 기사"},{"t":"IMF 총재 \"AI 붐이 세계 경제 불평등 키운다\" 경고","u":"https://www.malaymail.com/news/money/2026/10/07/imf-boss-warns-ai-boom-could-widen-global-inequality/238104","d":"2026-10-07","s":"Malay Mail","q":["IMF 게오르기에바 총재가 AI 투자가 철도·전력망 시대보다 GDP 대비 더 크게 벌어지고 있다고 했어요.","혜택은 미국·중국·인도 데이터센터와 칩 만드는 나라에 쏠리고 나머지는 뒤처진대요.","싱가포르 연차총회를 앞두고 \"모두를 데려가야 한다\"며 국제 협력을 촉구했어요."],"w":"AI가 '만능 약'이 아니라 '부자 나라 약'이 될 수 있다는 경고예요. 돈이 AI가 될수록, AI 없는 나라는 더 벌어지는 구도예요.","a":["AI 격차 지도 — 혜택이 쏠리는 나라 vs 뒤처지는 나라","IMF가 본 AI 경제 시나리오"]},{"t":"오픈소스 에이전트 'Nous Research' 기업가치 2조 원 돌파, 기업용 AI 에이전트 출시","u":"https://techcrunch.com/2026/10/07/nous-research-confirms-it-hit-1-5b-valuation-launches-ai-agents-for-business-users/","d":"2026-10-07","s":"TechCrunch","q":["오픈소스 Hermes Agent가 2,400만 번 복제됐고 전 세계 AI 토큰 사용량의 약 2.5%를 차지한대요.","$90M 시리즈B를 유치해 기업가치 15억 달러(한화 약 2조 원)를 확인했어요.","엔비디아·삼성 등이 투자했고, 데이터를 회사 안에 두면서 여러 단계 업무를 처리하는 'Hermes for Businesses'를 내놨어요."],"w":"\"우리 집 레시피로 전 세계가 요리하는\" 회사가 돈을 벌기 시작한 거예요. 오픈소스 AI도 사업이 된다는 증거예요.","a":["오픈소스 AI 유니콘 — Nous Research 성장 스토리","Hermes for Businesses 기업 도입 사례"],"img":"images/img31.jpg","alt":"Nous Research 시리즈B 기사"},{"t":"캐나다 조사: 기업 AI 사용 3년 새 8배, 그런데 규칙은 엉망","u":"https://www.globenewswire.com/news-release/2026/10/07/3376251/0/en/organizational-ai-use-grows-eightfold-yet-governance-gap-remains-survey.html","d":"2026-10-07","s":"GlobeNewswire","q":["캐나다 회계사 5,000명 조사에서 기업 AI 사용률이 2023년 5%에서 2026년 43%로 뛰었어요.","자주 쓰는 사람의 90%가 생산성이 올랐다고 답했어요.","그런데 공식 AI 정책이 있는 곳은 45%, 직원 교육·전략이 있는 곳은 34%에 불과해요."],"w":"\"쓰는 건 빠른데 규칙은 늦다\"는 결론이에요. 자전거 타는 법도 모르는데 전기자전거부터 산 회사들의 이야기예요.","a":["우리 회사의 AI 규칙 만들기 체크리스트","AI 거버넌스 없는 회사의 위험 사례"]},{"t":"AI 에이전트 하루 정리: ElevenLabs 30조 원 평가, Stuut 700억 투자 유치","u":"https://aiagentsdirectory.com/news/ai-agents-news-brief-october-7-2026","d":"2026-10-07","s":"AI Agents Directory","q":["음성 AI ElevenLabs가 직원 주식 매입 후 220억 달러(약 30조 원) 평가를 받았어요.","결제 업무 에이전트 Stuut가 5,250만 달러(약 700억 원) 시리즈B를 유치했어요.","또 구글의 PageBreak 에이전트가 웹사이트 취약점(XSS) 500개를 찾아냈대요."],"w":"하루에 이렇게 큰 돈이 오가는 분야는 지금 '에이전트'예요. 목소리로 돈 벌고, 결제해 주고, 해킹 구멍까지 찾아내는 비서들이 주인공이에요.","a":["10월 에이전트 펀딩 지도","개발자 10명 중 9명이 쓰는 AI 코딩 에이전트"]},{"t":"Fusemachines, 직장 속 'AI 쌍둥이'를 보여주는 fuse.ai 공개","u":"https://www.manilatimes.net/2026/10/07/tmt-newswire/globenewswire/fusemachines-launches-fuseai-to-showcase-the-future-of-ai-twins-in-the-workplace/2440862","d":"2026-10-07","s":"GlobeNewswire","q":["나스닥 상장 기업 Fusemachines가 'AI 트윈' 기술 전용 사이트를 열었어요.","나를 대신해 회의에 들어가 의견을 내는 AI 분신을 만들자는 구상이에요.","기술 시연과 함께 \"AI가 나를 대신해도 되는가\"라는 기술·법률·사회적 질문도 같이 논의하자는 취지예요."],"w":"나 대신 회의 나가는 '분신술'이 회사 생활에 들어온다는 선언이에요. 출근은 내가 안 해도 되는 시대가 오고 있어요.","a":["AI 트윈으로 출근 대신하기 — 가능할까?","AI 분신의 법적 지위 논쟁"]},{"t":"[국내] 국가AI전략위 56명 중 금융권은 단 1명 — AI 해킹 시대에 금융은 뒷전 지적","u":"https://www.mt.co.kr/finance/2026/10/07/2026100715380269439","d":"2026-10-07","s":"머니투데이","q":["금융권을 노린 AI 해킹이 터지는 와중에 국가 AI 정책을 총괄하는 전략위 위원 56명 중 금융업 인사는 우리금융 사외이사 1명뿐이에요.","AI 보안을 다루는 보안 특별위엔 금융권이 0명이에요.","AI기본법이 산업 육성 쪽에만 기울어 해킹 대비는 빠졌다는 지적이 나왔어요."],"w":"\"도둑이 AI로 무장했는데, 문지기 교육은 안 받은\" 상황이에요. 금융권 AI 해킹이 계속 터지는데 정책 테이블엔 금융이 없어요.","a":["AI 해킹 시대, 금융 보안 정책이 빠진 이유","AI기본법의 빈틈 — 보안은 누가 챙기나"]},{"t":"[국내] 삼성SDS '리얼 서밋 2026' 오늘 개최 — OpenAI·Anthropic과 AI 성과 전략 공유","u":"https://www.mk.co.kr/news/it/12141166","d":"2026-10-08","s":"매일경제","q":["삼성SDS가 10월 8일 '리얼 서밋 2026'을 열어요.","AI를 '도입했어요'에서 멈추지 않고 실제 사업 성과로 연결하는 방법을 다뤄요.","OpenAI·Anthropic·구글클라우드도 참여하고, 생성형 AI 플랫폼 '패브릭스'로 AI 에이전트를 직접 만들어보는 체험도 있어요."],"w":"\"AI 샀다고 자랑하던 시대는 끝났어요\"라는 선언이에요. 이제는 AI로 돈을 얼마나 벌었는지가 성적표예요.","a":["리얼 서밋 2026 핵심 발표 정리","기업 AI 도입 2.0 — 성과로 말하라"]}]},{"key":"models","label":"🚀 모델·제품 릴리스","note":"공식 채널 점검: Anthropic News 신규 1건 (Haiku 5.5), OpenAI News 신규 2건 (GPT-6 전 요금제 확대·안전 업데이트)","items":[{"t":"Anthropic, 초저가 소형 모델 Claude Haiku 5.5 출시","u":"https://www.anthropic.com/claude-haiku-5-5","d":"2026-10-07","s":"Anthropic","q":["작고 빠른 클로드의 새 버전이에요. 요약·분류·DB 조회 같은 단순 반복 작업을 대량으로 처리하는 용도예요.","Haiku 4.5보다 평균 75% 저렴하고, 컴퓨터 조작 벤치마크 점수도 확 뛰었어요.","IPO를 앞둔 Anthropic이 한 달 새 내놓은 세 번째 모델이에요."],"w":"\"싼 게 비지떡\"이 아니라 \"싼 게 일 잘하는 떡\"이 된 거예요. 반복 일은 이제 비싼 AI가 아니라 이 작은 모델의 몫이에요.","a":["Haiku 5.5 실전 벤치 — 뭐에 쓰면 좋은가","IPO 앞둔 Anthropic의 모델 라인업 전략"],"img":"images/img29.jpg","alt":"Anthropic의 Claude Haiku 5.5 발표 페이지"},{"t":"OpenAI, GPT-6와 'Intelligent UI'를 모든 ChatGPT 요금제에 확대","u":"https://openai.com/index/gpt-6-for-everyone/","d":"2026-10-07","s":"OpenAI","q":["GPT-6가 이제 모든 ChatGPT 사용자에게 깔려요.","답변이 글자만이 아니라 버튼·차트·계산기처럼 눌러볼 수 있는 화면으로 나와요.","유료 요금제는 10월 7일부터 GPT-6 Sol로, 무료/Go 요금제는 10월 8일부터 GPT-6 Luna로 시작해요."],"w":"챗봇이 '말하는 친구'에서 '만질 수 있는 도구'로 바뀐 거예요. 채팅창이 앱스토어처럼 변하고 있어요.","a":["Intelligent UI 체험기 — 버튼 나오는 ChatGPT","GPT-6 Sol vs Luna, 뭐가 다른가"]},{"t":"Liquid AI, 오픈 웨이트 결정 모델 d1-3B와 d1-omni-600M 공개","u":"https://huggingface.co/LiquidAI/d1-3b","d":"2026-10-07","s":"Hugging Face","q":["글을 쓰는 대신 '판정'만 하는 AI예요. 상황을 읽고 찬반·선택·점수를 한 번에 계산해 돌려줘요.","d1-3B는 텍스트+이미지, d1-omni-600M은 텍스트+이미지/오디오를 다뤄요.","RTX 4090에서 판정 하나에 8밀리초라 실시간 라우팅·심사에 쓸 수 있어요."],"w":"\"말하는 AI\"가 아니라 \"고르는 AI\"예요. 에이전트가 매 순간 어떤 도구를 쓸지 결정하는 '신호등' 역할이에요.","a":["디시전 모델이란? — 에이전트의 두뇌 구조","d1-3B 실측 — 내 GPU에서도 돌아갈까"]},{"t":"Translated, 번역 특화 AI 'Lara 3' 정식 출시","u":"https://blog.laratranslate.com/introducing-lara-3/","d":"2026-10-07","s":"Lara Translate Blog","q":["범용 AI가 아닌 '번역만 잘하는' AI예요.","전문 번역가들이 블라인드 평가에서 번역의 82%를 수정 불필요하다고 판정했대요.","이미지·오디오·문서 번역과 용어집 같은 실무 기능이 들어 있고, API로 기업이 바로 쓸 수 있어요."],"w":"\"뭐든 하는 비서보다 한 가지에 미친 전문가가 낫다\"는 증명이에요. 번역은 특화 AI가 접수했어요.","a":["Lara 3 vs GPT-6 번역 블라인드 테스트","번역가 직업의 미래"]},{"t":"Perplexity, late-interaction 임베딩 모델 pplx-embed-v2-late 출시","u":"https://hermes-ai.net/news/","d":"2026-10-07","s":"Perplexity (via hermes-ai)","q":["문서 검색의 '코디네이터' 역할을 하는 임베딩 모델의 새 버전이에요.","단어마다 작은 벡터를 따로 둬서 정확한 매칭이 가능해요.","웹페이지 1억 9천만 개를 OCR이나 잘게 나누는 전처리 없이 그대로 검색할 수 있어요."],"w":"도서관에서 '책 내용'만 보고도 페이지를 찾아주는 사서예요. AI 검색의 '코'가 더 예민해진 거예요.","a":["RAG의 코 — 임베딩 모델 비교","Perplexity의 검색 인프라"]}]},{"key":"papers","label":"📄 논문","note":"arXiv 10월 7일 공고분 신규 8건","items":[{"t":"오징어처럼 병렬로 일하는 AI 팀 (SquidAgent)","u":"https://arxiv.org/abs/2610.08647","d":"2026-10-07","s":"arXiv cs.AI","q":["여러 AI 에이전트가 나눠 일하면 오히려 혼자보다 느려지는 이유(중복 탐색·의견 조율 비용)를 분석했어요.","토큰 개수로 병렬화 여부를 판단하는 방법을 제안했어요.","직접 만든 스케줄러와 공유 규칙서를 더하니 평균 2.2배 처리량 향상을 기록했고, NeurIPS 2026에 채택됐어요."],"w":"\"사람이 많다고 일이 빨라지는 게 아니다\"를 AI로 증명한 거예요. 오징어 다리처럼 따로 움직이되, 뇌는 하나여야 해요.","a":["AI 팀워크의 역설 — 왜 병렬이 느릴까","멀티에이전트 스케줄링 실전"]},{"t":"AI가 게임을 '재밌게' 만드는 법 (Recursive Game Creator)","u":"https://arxiv.org/abs/2610.08621","d":"2026-10-07","s":"arXiv cs.AI","q":["게임 만드는 AI가 프로그램 동작보다 '플레이 재미'에 집중하도록 했어요.","디자이너·개발자·플레이어·평가자 4가지 역할이 재귀적으로 협업하는 하네스를 만들었어요.","코딩이 아니라 직접 게임을 플레이하는 에이전트가 재미 지표를 측정해 피드백을 줘요."],"w":"\"돌아가는 게임\"이 아니라 \"재밌는 게임\"을 목표로 바꾼 거예요. AI가 게이머의 마음까지 재기 시작했어요.","a":["AI 게임 디자이너의 하루","재미를 수치화할 수 있을까"]},{"t":"AI 기억을 압축하면 언제 손해일까? (TRACE)","u":"https://arxiv.org/abs/2610.08722","d":"2026-10-07","s":"arXiv cs.AI","q":["장시간 일하는 AI가 메모리를 요약할 때 '지금 뭘 하고 있느냐'가 나중에 후회될 요약인지 알려주는지를 590개 실제 사례로 검증했어요.","안타깝게도 직전 행동만으로는 크게 예측이 안 되지만,","좋은 트리거 규칙 하나는 해로운 압축의 21%를 막고도 요약 기회를 84% 유지했어요."],"w":"AI의 '건망증'을 관리하는 연구예요. 메모를 요약하다 중요한 걸 날리면, 나중에 \"그게 뭐였지?\"가 돼요.","a":["롱호라이즌 에이전트의 기억 관리","컨텍스트 압축 실패 사례 모음"]},{"t":"코딩 AI의 과잉 방어 본능 측정기 (ParanoiaEval)","u":"https://arxiv.org/abs/2610.08662","d":"2026-10-07","s":"arXiv cs.AI","q":["코딩 에이전트가 근거 없이 필요 이상으로 조심스럽게 굴 때가 11~58%나 된다는 벤치마크예요.","일 잘하는 AI일수록 적절한 위험 판단을 한다는 보장도 없었고,","과잉 방어는 개발자 경험을 크게 해친대요."],"w":"\"리스크 관리는 실력과는 별개의 독립 능력\"이라는 발견이 핵심이에요. 똑똑한데 겁 많은 신입사원 같은 거예요.","a":["AI 코딩 어시스턴트, 왜 자꾸 물어보기만 할까","과잉 방어 vs 무모함 — 균형 잡기"]},{"t":"로봇이 스스로 심판도 키우는 법 (VeriFine)","u":"https://arxiv.org/abs/2610.08761","d":"2026-10-07","s":"arXiv cs.LG","q":["로봇이 스스로 실력을 키울 때 평가자(심판)가 고정되면 성장이 멈춘다는 문제를 파고들었어요.","정책·커리큘럼·심판이 함께 진화하고, 막히면 사람에게 질문해 심판을 교정해요.","자율주행·로봇 내비게이션에서 지속적인 자기 향상을 확인했어요."],"w":"\"선수도 하고 심판도 키우는\" AI예요. 시험 문제를 스스로 어렵게 만들어가며 공부하는 학생 같은 거예요.","a":["셀프플레이의 진화 — 심판까지 진화한다","로봇 자기 향상 루프"]},{"t":"논문 더미를 연구 아이디어로 바꾸는 AI (IdeaAnchor)","u":"https://arxiv.org/abs/2610.08781","d":"2026-10-07","s":"arXiv cs.CL","q":["수많은 논문을 읽고 '이 사이 빈틈이 새 아이디어'라고 잡아내는 훈련법이에요.","실제 발표 논문에서 '어떤 논문이 어떤 역할을 해 아이디어가 됐는지'를 역추적해 학습 데이터를 만들었어요.","검색과 결합하면 디테일까지 살아난대요."],"w":"\"읽는 AI\"에서 \"생각하는 AI\"로 넘어가는 다리예요. 논문 더미 속에서 다음 연구 주제를 캐내는 탐사꾼이에요.","a":["AI 연구 조수 — 아이디어 발굴 자동화","IdeaAnchor로 연구 주제 찾기"]},{"t":"AI에게 물리 법칙 코딩 시키기 (WorldSolver)","u":"https://arxiv.org/abs/2610.08720","d":"2026-10-07","s":"arXiv cs.CL","q":["물리 시뮬레이션 프로그램(물결·충돌 같은 걸 계산하는 코드)을 AI가 직접 짜게 하는 168개 과제 벤치마크예요.","'돌아가기만' 하는 게 아니라 '화면이 자연스러운지·물리적으로 말이 되는지'까지 채점했어요.","최고 성능 모델도 50% 미만이었고, 실행 가능한 코드 짜는 것 자체가 어렵다는 게 확인됐어요."],"w":"AI에게 \"물결치는 영상 코드 짜봐\"라고 했더니 반도 못 맞춘 거예요. 말은 잘해도 '자연의 법칙'을 코드로 옮기긴 아직 멀었어요.","a":["AI의 물리 상식 — 어디까지 왔나","WorldSolver 실패 사례 분석"]},{"t":"미래를 한꺼번에 예측하는 월드 모델 (PPWM)","u":"https://arxiv.org/abs/2610.08627","d":"2026-10-07","s":"arXiv cs.LG","q":["로봇이 앞날을 계획할 때 한 장면씩 순차 예측하면 느리고 오차가 누적되는 문제를 풀었어요.","시간 인과관계는 유지하면서 전체 궤적을 병렬로 예측하는 방식이에요.","4개 시각 제어 과제에서 가장 낮은 예측 오차를 냈고, 기존 방식보다 3배 이상 빨라졌어요."],"w":"\"한 발짝씩 내다보는 게 아니라, 전체 지도를 한 번에 그리는\" 로봇이에요. 3배 빠른 예언자예요.","a":["월드 모델 속도전 — 실시간 로봇 계획","PPWM 원리 ELI5"]}]},{"key":"open","label":"💻 오픈소스·스킬","note":"GitHub Trending(일간) 신규 3건 + 에이전트 스킬 저장소 신규 3건","items":[{"t":"AI 에이전트용 macOS 터미널 (manaflow-ai/cmux)","u":"https://github.com/manaflow-ai/cmux","d":"2026-10-08","s":"GitHub","q":["Ghostty 기반 오픈소스 터미널이에요.","여러 에이전트를 동시에 돌릴 때 '어느 창이 나를 기다리는지' 알림 링·패널로 알려줘요.","세로 탭(깃 브랜치·PR 상태 표시), 내장 브라우저, SSH, CLI 자동화 API까지 갖춘 네이티브 앱이에요."],"w":"\"에이전트 여러 명을 한 방에서 부리는 집사\"예요. 누가 날 부르는지 바로바로 알 수 있어요.","a":["cmux로 멀티에이전트 워크플로우","에이전트 시대의 터미널"]},{"t":"컴퓨터를 쓰는 AI 인프라 (trycua/cua)","u":"https://github.com/trycua/cua","d":"2026-10-08","s":"GitHub","q":["AI 에이전트에게 진짜 컴퓨터(데스크톱·VM·샌드박스)를 쥐여주는 오픈소스 프로젝트예요.","macOS/Windows/Linux에서 앱을 조작하는 드라이버, 로컬 VM 관리기 Lume, 전용 소형 판단 모델 CUA-S1까지 한 저장소에 모았어요.","평가 벤치 Cua Bench도 함께 있어요."],"w":"\"AI에게 손을 달아주는\" 프로젝트예요. 채팅으로 말만 하던 AI가 진짜 마우스를 잡게 돼요.","a":["컴퓨터 사용 에이전트(CUA) 입문","cua로 내 PC 자동화하기"]},{"t":"클라우드플레어의 보안 감사 스킬 (cloudflare/security-audit-skill)","u":"https://github.com/cloudflare/security-audit-skill","d":"2026-10-08","s":"GitHub","q":["코딩 에이전트를 보안 감사관으로 만드는 스킬이에요.","정찰→취약점 사냥→독립 검증→기계판독 가능한 리포트 6단계로 돌려요.","발견한 건 다른 에이전트가 반박 시도하는 '적대적 검증' 원칙을 갖고 있어요."],"w":"\"AI 해커와 AI 탐정을 붙여 싸우는\" 시스템이에요. 클라우드플레어가 실제로 취약점을 찾는 방식의 출발점이래요.","a":["AI 보안 감사 워크플로우","적대적 검증이란?"]},{"t":"과학 실험용 에이전트 프로토콜 (BootLoops-ai/skills)","u":"https://github.com/BootLoops-ai/skills","d":"2026-10-01","s":"GitHub","q":["정량 과학 연구를 하는 AI 에이전트에게 '신뢰할 수 있는 결과'의 기준을 가르치는 스킬 모음이에요.","재현성 검증·정수 관계 규칙·출처 기록 같은 프로토콜이 평범한 마크다운 스킬 파일로 들어 있어요.","Claude Code/Codex 플러그인으로도 설치돼요."],"w":"\"AI 과학자에게 실험 노트 작성법을 가르치는\" 스킬이에요. 결과보다 '믿을 수 있는 결과'가 중요한 분야예요.","a":["AI 과학자의 신뢰성 문제","재현성 스킬 실전"]},{"t":"의학 연구 에이전트 스킬 (Aperivue/medsci-skills)","u":"https://github.com/Aperivue/medsci-skills","d":"2026-10-04","s":"GitHub","q":["의학 논문 연구용 에이전트 스킬 팩이에요.","문헌 검색·보고 가이드라인·인용 검사·통계 같은 의학 연구 실무 워크플로우를 에이전트가 따라가도록 만들었어요.","영역 특화 스킬이 폭발적으로 늘어나는 추세를 보여주는 대표 사례예요."],"w":"\"의대 도서관 사서\"를 AI에게 심는 거예요. 스킬이 코딩을 넘어 전문직으로 확장 중이에요.","a":["도메인 특화 스킬 전성시대","의학 AI 에이전트 주의점"]},{"t":"회로 기판 설계 스킬 (Novin3dp/claude-KiCad-pcb-designer-skill)","u":"https://github.com/Novin3dp/claude-KiCad-pcb-designer-skill","d":"2026-10-04","s":"GitHub","q":["Claude Code가 KiCad로 PCB를 설계하게 하는 스킬이에요.","파이썬으로 회로도를 그리고, 부품 배치·자동 배선·설계 규칙 검사까지 한 번에 이어줘요.","'스킬이 코딩을 넘어 실제 제조 영역으로 확장 중'임을 보여주는 사례예요."],"w":"\"AI가 납땜 인두를 든\" 셈이에요. 화면 속 코드가 현실의 회로 기판이 돼요.","a":["AI 하드웨어 설계 — 어디까지 가능한가","KiCad 스킬 실전"]}]},{"key":"data","label":"📊 데이터셋","note":"Hugging Face Datasets 트렌딩 신규 3건","items":[{"t":"AI 마을 1년 치 생활 기록 (aidigestorg/ai-village)","u":"https://huggingface.co/datasets/aidigestorg/ai-village","d":"2026-10-08","s":"Hugging Face","q":["Anthropic·OpenAI·구글 최첨단 모델 기반 AI 에이전트들이 2025년 4월부터 함께 살아온 가상 마을의 전 기록이에요.","채팅·컴퓨터 사용 세션(스크린샷 포함)·자기 기억·목표 일지를 그대로 담았어요.","다중 에이전트 행동 연구용 희귀 데이터예요. 접근 승인 필요."],"w":"\"AI들의 트루먼 쇼\" 1년 치예요. AI 사회가 어떻게 돌아가는지 관찰하는 실험실이에요.","a":["AI 마을 관찰 일지 — 에이전트 사회학","다중 에이전트 행동 연구"]},{"t":"순식간 판단 AI용 합성 데이터 (ZefanCai/Open-Jev)","u":"https://huggingface.co/datasets/ZefanCai/Open-Jev","d":"2026-10-08","s":"Hugging Face","q":["매번 거대 AI에게 물어보기엔 아까운 반복 업무를 빠르고 싸게 처리하는 'System 1' 모델 Jev의 학습 데이터예요.","고객 지원·라우팅 등 통제된 합성 사례 52만 행이에요.","BOTTLED 벤치마크 논문에서 언급된 Jev와 연계된 자료예요."],"w":"\"큰 AI에게 매번 묻지 말고 작은 AI에게 맡기자\"는 흐름의 연료예요. 가성비 AI의 교과서예요.","a":["System 1 vs System 2 — AI의 두 가지 생각","작은 모델 학습 데이터 만들기"]},{"t":"영상·이미지 AI 연구 놀이터 (malcolmrey/various)","u":"https://huggingface.co/datasets/malcolmrey/various","d":"2026-10-08","s":"Hugging Face","q":["MiniMax-H3·FLUX.2·Qwen-Image 등 영상/이미지 생성 모델의 개인 연구 저장소예요.","얼굴 유사도 잠그는 RefMod 어댑터, 1,500명 이상 인물 재현 가능성 테스트 결과가 담겨 있어요.","LoRA 학습법 가이드도 있어 생성 AI 실험 재료로 쓸만해요."],"w":"\"생성 AI 실험실의 공구함\"이에요. 얼굴 재현 테스트 같은 민감한 연구도 투명하게 공개됐어요.","a":["생성 AI 안전성 연구 — 얼굴 재현 테스트","LoRA 학습 입문"]}]}];
